class ToolRegistry:
    """工具注册中心"""

    def __init__(self):
        self.tools: Dict[str, ToolSchema] = {}
        self.categories: Dict[ToolCategory, List[str]] = {cat: [] for cat in ToolCategory}

    def register(self, 
                 name: str,
                 description: str,
                 category: ToolCategory,
                 parameters: Dict,
                 required: List[str],
                 dangerous: bool = False):
        """注册工具装饰器"""
        def decorator(func: Callable):
            tool = ToolSchema(
                name=name,
                description=description,
                category=category,
                parameters=parameters,
                required=required,
                handler=func,
                dangerous=dangerous
            )
            self.tools[name] = tool
            self.categories[category].append(name)
            return func
        return decorator

    def get_tool(self, name: str) -> Optional[ToolSchema]:
        """获取工具"""
        return self.tools.get(name)

    def list_tools(self, category: Optional[ToolCategory] = None) -> List[ToolSchema]:
        """列出工具"""
        if category:
            return [self.tools[name] for name in self.categories[category]]
        return list(self.tools.values())

    def get_schemas(self) -> List[Dict]:
        """获取所有Schema（用于LLM）"""
        return [tool.to_openai_format() for tool in self.tools.values()]

    def execute(self, name: str, arguments: Dict) -> Dict:
        """执行工具"""
        tool = self.tools.get(name)
        if not tool:
            return {
                "error": f"工具未找到: {name}",
                "status": "failed"
            }

        # 参数验证
        validation = self._validate_params(tool, arguments)
        if not validation["valid"]:
            return {
                "error": validation["error"],
                "status": "failed"
            }

        # 危险操作确认
        if tool.dangerous:
            # 记录审计日志
            print(f"[龍魂·审计] 危险操作: {name}({arguments})")

        try:
            # 执行
            result = tool.handler(**arguments)
            return {
                "result": result,
                "status": "success",
                "tool": name,
                "dna": tool.dna_signature
            }
        except Exception as e:
            return {
                "error": str(e),
                "status": "failed",
                "tool": name
            }

    def _validate_params(self, tool: ToolSchema, arguments: Dict) -> Dict:
        """参数验证"""
        # 检查必填参数
        for req in tool.required:
            if req not in arguments:
                return {
                    "valid": False,
                    "error": f"缺少必填参数: {req}"
                }

        # 类型检查（简化版）
        for key, value in arguments.items():
            if key in tool.parameters:
                expected_type = tool.parameters[key].get("type", "string")
                # 简化类型检查
                if expected_type == "number" and not isinstance(value, (int, float)):
                    return {
                        "valid": False,
                        "error": f"参数 {key} 应为数字类型"
                    }

        return {"valid": True}


