@registry.register(
    name="calculate_math",
    description="执行数学计算，支持基本运算和函数",
    category=ToolCategory.CALCULATION,
    parameters={
        "expression": {
            "type": "string",
            "description": "数学表达式，如 '2 + 2 * 3' 或 'sin(30)'"
        }
    },
    required=["expression"]
)
def calculate_math(expression: str) -> str:
    """数学计算工具"""
    import math
    import ast

    # 安全评估：只允许数学运算
    allowed_names = {
        "abs": abs, "max": max, "min": min,
        "pow": pow, "sqrt": math.sqrt,
        "sin": math.sin, "cos": math.cos, "tan": math.tan,
        "log": math.log, "log10": math.log10,
        "pi": math.pi, "e": math.e
    }

    try:
        # 解析表达式
        tree = ast.parse(expression, mode='eval')

        # 安全检查
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                if not isinstance(node.func, ast.Name) or node.func.id not in allowed_names:
                    raise ValueError(f"不允许的函数调用: {node.func}")

        result = eval(compile(tree, '', 'eval'), {"__builtins__": {}}, allowed_names)
        return f"计算结果: {result}"
    except Exception as e:
        return f"计算错误: {str(e)}"


@registry.register(
    name="solve_equation",
    description="求解方程，支持一元二次方程等",
    category=ToolCategory.CALCULATION,
    parameters={
        "equation": {
            "type": "string",
            "description": "方程表达式，如 'x^2 + 5x + 6 = 0'"
        },
        "variable": {
            "type": "string",
            "description": "变量名，如 'x'"
        }
    },
    required=["equation", "variable"]
)
def solve_equation(equation: str, variable: str) -> str:
    """方程求解工具"""
    try:
        from sympy import symbols, solve, Eq, parse_expr

        var = symbols(variable)
        # 解析方程
        if '=' in equation:
            left, right = equation.split('=')
            eq = Eq(parse_expr(left), parse_expr(right))
        else:
            eq = parse_expr(equation)

        solutions = solve(eq, var)

        if not solutions:
            return "方程无解"

        result = f"方程 {equation} 的解:\n"
        for i, sol in enumerate(solutions, 1):
            result += f"  x{i} = {sol}\n"

        return result
    except ImportError:
        return "错误: 请安装sympy库"
    except Exception as e:
        return f"求解错误: {str(e)}"


