      Row() {
        if (msg.role === 'assistant') {
          Text('🐉').fontSize(20)
          Text('龍魂AI').fontSize(12).fontColor('#c41e3a').margin({ left: 4 })
        } else {
          Text('👤').fontSize(20)
          Text('我').fontSize(12).fontColor('#00ff00').margin({ left: 4 })
        }
      }
      .width('100%')
      .justifyContent(msg.role === 'assistant' ? FlexAlign.Start : FlexAlign.End)
      .margin({ bottom: 4 })

      // 内容气泡
      Column() {
        Text(msg.content)
          .fontSize(14)
          .fontColor('#fff')
