              Text(`置信度: ${(msg.confidence * 100).toFixed(1)}%`)
                .fontSize(10)
                .fontColor(msg.confidence > 0.8 ? '#00ff00' : '#ffcc00')
                .margin({ left: 8 })
            }
          }
          .width('100%')
          .margin({ top: 8 })

          // 工具使用
          if (msg.toolsUsed && msg.toolsUsed.length > 0) {
            Row() {
              Text('🔧').fontSize(10)
              Text(msg.toolsUsed.join(', ')).fontSize(10).fontColor('#888').margin({ left: 4 })
            }
            .width('100%')
            .margin({ top: 4 })
          }

          // 来源引用
          if (msg.sources && msg.sources.length > 0) {
            Button('查看来源').fontSize(11).fontColor('#c41e3a').backgroundColor('transparent').onClick(() => {
              this.selectedMessage = msg;
              this.showSources = true;
            })
          }
        }
      }
      .width('85%')
      .padding(12)
      .backgroundColor(msg.role === 'assistant' ? '#1a1a1a' : '#0d2d0d')
      .borderRadius(12)
      .alignSelf(msg.role === 'assistant' ? ItemAlign.Start : ItemAlign.End)
      .margin({ bottom: 8 })
    }
    .width('100%')
    .alignItems(msg.role === 'assistant' ? HorizontalAlign.Start : HorizontalAlign.End)
  }

  @Builder
  InputAreaBuilder() {
    Row() {
      TextInput({ placeholder: '输入问题...', text: $$this.inputText })
        .width('75%')
        .height(44)
        .fontSize(14)
        .fontColor('#fff')
        .placeholderColor('#666')
        .backgroundColor('#1a1a1a')
        .borderRadius(8)
        .padding({ left: 12, right: 12 })
        .onSubmit(() => {
          this.sendMessage();
        })

      Button(this.isLoading ? '⏳' : '发送')
        .width('20%')
        .height(44)
        .fontSize(14)
        .fontColor('#fff')
        .backgroundColor(this.isLoading ? '#333' : '#c41e3a')
        .borderRadius(8)
        .enabled(!this.isLoading)
        .onClick(() => {
          this.sendMessage();
        })
    }
    .width('100%')
    .height(60)
    .padding({ left: 12, right: 12, top: 8, bottom: 8 })
    .backgroundColor('#1a1a1a')
    .border({ width: { top: 1 }, color: '#333' })
  }

  // === 发送消息 ===
  async sendMessage() {
    if (!this.inputText.trim() || this.isLoading) return;

    const userMsg: ChatMessage = {
      id: `USER-${Date.now()}`,
      role: 'user',
      content: this.inputText,
      timestamp: new Date().toISOString()
    };

    this.messages.push(userMsg);
    const question = this.inputText;
    this.inputText = '';
    this.isLoading = true;

    try {
      // 调用后端API
      const response = await http.createHttp().request(`${API_BASE}/chat`, {
        method: http.RequestMethod.POST,
        header: { 'Content-Type': 'application/json' },
        extraData: JSON.stringify({
          message: question,
          session_id: this.sessionId
        })
      });

      const result = JSON.parse(response.result.toString());

      const aiMsg: ChatMessage = {
        id: `AI-${Date.now()}`,
        role: 'assistant',
        content: result.response,
        intent: result.intent,
        sources: result.sources,
        confidence: result.confidence,
        toolsUsed: result.tools_used,
        timestamp: new Date().toISOString()
      };

      this.messages.push(aiMsg);
    } catch (e) {
      this.messages.push({
        id: `ERROR-${Date.now()}`,
        role: 'assistant',
        content: `❌ 请求失败: ${e.message}`,
        timestamp: new Date().toISOString()
      });
    } finally {
      this.isLoading = false;
    }
  }

  // === 工具对话框 ===
  showToolsDialog() {
    // 显示可用工具列表
    // 实际实现：调用 /api/v1/tools/list
  }
}

