// === 对联数据 ===
export class CoupletData {
  id: string;
  upper: string;                 // 上联
  lower: string;                 // 下联
  horizontal: string;            // 横批
  theme: string;                 // 主题
  tonePattern: string;           // 平仄格式
  wordCount: number;             // 字数
  dnaSignature: string;

  constructor(data: Partial<CoupletData> = {}) {
    this.id = data.id || `COUPLET-${Date.now()}`;
    this.upper = data.upper || '';
    this.lower = data.lower || '';
    this.horizontal = data.horizontal || '';
    this.theme = data.theme || '';
    this.tonePattern = data.tonePattern || '';
    this.wordCount = data.wordCount || 7;
    this.dnaSignature = this.signData();
  }

  private signData(): string {
    const payload = `${this.id}-${this.upper}-${this.lower}-${Date.now()}`;
    return `SM3-${this.hashCode(payload)}`;
  }

  private hashCode(str: string): string {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = ((hash << 5) - hash) + str.charCodeAt(i);
      hash = hash & hash;
    }
    return Math.abs(hash).toString(16).substring(0, 16);
  }
}

